def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    aggressive_bids = []
    moderate_bids = []

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 90:
                    aggressive_bids.append(bid)
                else:
                    moderate_bids.append(bid)

    if budget <= 0:
        return 0.0

    guaranteed_units = int(supply // WATER_REQ)
    scarcity = guaranteed_units <= 1

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_max = max(moderate_bids) if moderate_bids else 55.0

    emergency = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if critical:
        bid = max(92.0, moderate_max + 6.0)
        if scarcity:
            bid = max(bid, 108.0)
        return float(min(budget, bid))

    if scarcity:
        if aggressive_bids:
            bid = moderate_max + 3.0
            bid = max(58.0, min(bid, 76.0))
        else:
            bid = max(60.0, moderate_max + 2.0)
        if emergency:
            bid = max(bid, 82.0)
        return float(min(budget, bid))

    bid = max(22.0, moderate_max - 6.0)

    if highest_prev >= 120:
        bid = min(bid, 44.0)
    elif highest_prev >= 90:
        bid = min(max(28.0, moderate_max - 8.0), 48.0)
    else:
        bid = max(35.0, moderate_max + 1.5)

    if emergency:
        bid = max(bid, moderate_max + 4.0)
        bid = max(bid, 68.0)

    if day >= 8 and hp >= 5 and no_water_days == 0:
        bid = min(bid, 32.0)

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day))
    if budget < reserve_floor * 0.45 and not emergency:
        bid = min(bid, 30.0)

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if not yesterday_bids:
        # No info: bid safely
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.4)
    max_prev = max(yesterday_bids)
    avg_prev = sum(yesterday_bids) / len(yesterday_bids)
    # Supply influences aggressiveness
    supply = day_context['supply']
    # Estimate how many players can get water: number of alive players
    num_alive = len(alive_opponents)
    # If supply high relative to players, can bid lower
    if my_status['hp'] <= 2:
        # desperate
        target = max(max_prev + 1.0, DAILY_SALARY * 0.85)
    elif num_alive > 0 and supply >= WATER_REQ * (num_alive + 1):
        # plenty of water, just need to be at least average
        target = max(avg_prev, DAILY_SALARY * 0.3)
    else:
        # tight supply, bid above max
        target = max_prev + 1.0
    # ensure within budget and not more than salary
    bid = min(my_status['budget'], target)
    bid = min(bid, DAILY_SALARY * 1.0)  # never bid more than salary
    # Also cannot bid negative
    if bid < 0:
        bid = 0
    return bid
